el><input id="storage-min-capacity" name="min_capacity" type="number" min="1" step="0.01" value="<?= e((string) ($filters['min_capacity'] ?? '')) ?>"></div><div class="form-field"><label for="storage-max-price">Maximum daily price (Rs./kg)</label><input id="storage-max-price" name="max_price" type="number" min="0.01" step="0.01" value="<?= e((string) ($filters['max_price'] ?? '')) ?>"></div><div class="form-field"><label for="storage-sort">Sort storage</label><select id="storage-sort" name="sort"><option value="capacity_high" <?= $filters['sort'] === 'capacity_high' ? 'selected' : '' ?>>Most capacity</option><option value="price_low" <?= $filters['sort'] === 'price_low' ? 'selected' : '' ?>>Price: low to high</option><option value="price_high" <?= $filters['sort'] === 'price_high' ? 'selected' : '' ?>>Price: high to low</option><option value="recent" <?= $filters['sort'] === 'recent' ? 'selected' : '' ?>>Recently updated</option></select></div><div class="filter-actions"><button class="button button-primary" type="submit">Update storage</button><a class="button button-quiet" href="<?= e(app_url('storage/index.php')) ?>">Clear</a></div></form></aside><div class="storage-discovery-results"><div class="results-bar"><p data-storage-feedback aria-live="polite"><?= count($facilities) ?> storage facilit<?= count($facilities) === 1 ? 'y' : 'ies' ?> shown.</p></div><div class="service-grid" data-storage-results><?= storage_facility_cards_html($facilities, $farmer) ?></div></div></div></div></section>
